sp_css.css:
/* =========================
   Library Portal – Global UI
   ========================= */

/* ---- Tokens / base ---- */
:root {
  --lib-max-width: 1200px;
  --lib-gap: 12px;

  --lib-radius: 10px;
  --lib-border: rgba(0,0,0,0.12);
  --lib-border-strong: rgba(0,0,0,0.22);

  --lib-text: rgba(0,0,0,0.90);
  --lib-text-muted: rgba(0,0,0,0.65);
  --lib-bg-muted: rgba(0,0,0,0.04);
  --lib-bg-hover: rgba(0,0,0,0.05);
}

/* A nice default wrapper you can use in page containers if you want */
.lib-container {
  max-width: var(--lib-max-width);
  margin: 0 auto;
  padding: 0 16px;
}

/* ---- Generic widget spacing ---- */
.lib-widget {
  margin: 18px 0;
}

.lib-widget--dense {
  margin: 10px 0;
}

.lib-widget-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}

.lib-widget-title {
  font-weight: 700;
  font-size: 16px;
  color: var(--lib-text);
}

/* ---- Helpers ---- */
.lib-empty,
.lib-error {
  padding: 12px 0;
  color: var(--lib-text-muted);
}

.lib-error {
  color: rgba(155, 0, 0, 0.85);
}

.lib-meta-link,
.lib-back-link {
  color: rgba(0,0,0,0.75);
  text-decoration: none;
  font-weight: 600;
}

.lib-meta-link:hover,
.lib-back-link:hover {
  text-decoration: underline;
}

/* =========================
   Cards + Grid (shared)
   ========================= */

.lib-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--lib-gap);
}

.lib-card {
  display: block;
  text-decoration: none;
  border: 1px solid var(--lib-border);
  border-radius: var(--lib-radius);
  overflow: hidden;
  background: #fff;
  transition: border-color 120ms ease, transform 120ms ease;
}

.lib-card:hover {
  border-color: var(--lib-border-strong);
  transform: translateY(-1px);
}

.lib-card-image {
  background: var(--lib-bg-muted);
  position: relative;
  overflow: hidden;
}

/* GRID cover: consistent aspect ratio */
.lib-grid .lib-card-image {
  aspect-ratio: 2 / 3; /* book-ish */
}

/* The actual image */
.lib-card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* Placeholder when no image */
.lib-card-image-placeholder {
  width: 60%;
  height: 70%;
  margin: 0 auto;
  border: 1px dashed rgba(0,0,0,0.25);
  border-radius: 8px;
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
}

.lib-seq-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  padding: 6px 8px;
  border-radius: 10px;
  background: rgba(255,255,255,0.92);
  border: 1px solid var(--lib-border);
  font-weight: 700;
  font-size: 12px;
  color: rgba(0,0,0,0.85);
}

.lib-card-body {
  padding: 10px 12px 12px;
}

.lib-card-title {
  font-weight: 650;
  color: rgba(0,0,0,0.92);
  line-height: 1.2;
}

.lib-card-subtitle {
  margin-top: 6px;
  font-size: 12px;
  color: var(--lib-text-muted);
}

/* =========================
   Carousel (books_browser)
   ========================= */

.lib-carousel {
  position: relative;
}

/* viewport with room for arrows */
.lib-carousel-viewport {
  overflow-x: auto;
  scroll-behavior: smooth;
  padding: 6px 34px;
}

/* horizontal track */
.lib-carousel-track {
  display: flex;
  gap: var(--lib-gap);
}

/* Carousel cards: set width and cover ratio smaller */
.lib-card--carousel {
  flex: 0 0 170px; /* card width; adjust if you want */
}

/* Carousel cover: smaller & consistent */
.lib-card--carousel .lib-card-image {
  aspect-ratio: 2 / 3;
}

/* Arrow buttons */
.lib-carousel-btn {
  position: absolute;
  top: 42%;
  transform: translateY(-50%);
  width: 28px;
  height: 48px;
  border-radius: 10px;
  border: 1px solid var(--lib-border);
  background: rgba(255,255,255,0.92);
  font-size: 22px;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
  z-index: 2;
}

.lib-carousel-btn:hover {
  background: #fff;
  border-color: var(--lib-border-strong);
}

.lib-carousel-btn--left { left: 0; }
.lib-carousel-btn--right { right: 0; }

/* Optional: hide scrollbar on webkit (purely cosmetic) */
.lib-carousel-viewport::-webkit-scrollbar {
  height: 10px;
}
.lib-carousel-viewport::-webkit-scrollbar-thumb {
  background: rgba(0,0,0,0.12);
  border-radius: 10px;
}
.lib-carousel-viewport::-webkit-scrollbar-track {
  background: rgba(0,0,0,0.04);
}

/* =========================
   Record detail
   ========================= */

.lib-record-detail {
  margin: 18px 0;
}

.lib-back {
  margin-bottom: 12px;
}

.lib-detail-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 18px;
  align-items: start;
}

/* Cover wrapper */
.lib-detail-cover {
  border: 1px solid var(--lib-border);
  border-radius: var(--lib-radius);
  background: var(--lib-bg-muted);
  overflow: hidden;
  width: 100%;
  aspect-ratio: 2 / 3;
}

.lib-detail-cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.lib-detail-cover-placeholder {
  width: 60%;
  height: 70%;
  margin: 0 auto;
  border: 1px dashed rgba(0,0,0,0.25);
  border-radius: 8px;
  position: relative;
  top: 15%;
}

.lib-detail-title {
  margin: 0 0 10px;
  font-size: 28px;
  line-height: 1.15;
  font-weight: 800;
  color: var(--lib-text);
}

.lib-detail-meta {
  border: 1px solid var(--lib-border);
  border-radius: var(--lib-radius);
  padding: 10px 12px;
  background: #fff;
}

.lib-detail-meta-row {
  display: grid;
  grid-template-columns: 180px 1fr;
  gap: 10px;
  padding: 6px 0;
  border-bottom: 1px solid rgba(0,0,0,0.06);
}

.lib-detail-meta-row:last-child {
  border-bottom: 0;
}

.lib-detail-meta-label {
  font-weight: 650;
  color: rgba(0,0,0,0.78);
}

.lib-detail-meta-value {
  color: rgba(0,0,0,0.90);
}

.lib-detail-desc {
  margin-top: 14px;
}

.lib-detail-desc-short {
  color: rgba(0,0,0,0.85);
  font-weight: 600;
  margin-bottom: 8px;
}

.lib-detail-desc-long {
  color: rgba(0,0,0,0.82);
  line-height: 1.55;
}

/* =========================
   Responsive tweaks
   ========================= */
@media (max-width: 900px) {
  .lib-detail-layout {
    grid-template-columns: 200px 1fr;
  }
}

@media (max-width: 720px) {
  .lib-detail-layout {
    grid-template-columns: 1fr;
  }

  .lib-detail-cover {
    max-width: 320px;
  }

  .lib-detail-meta-row {
    grid-template-columns: 1fr;
  }
}
